html:
{#- MMG Doctor Payout: the receipt of money paid to a doctor (DOC-09), a simple one until the final design (week C).
    Arabic (right-to-left) when printed in Arabic, English otherwise, like MMG Sales Invoice. Any other kind of
    entry in the doctor's ledger prints the same way under its own title. -#}
{%- set ar = _("Invoice") != "Invoice" -%}
{%- set L = {
	"title": ("Doctor Payout Receipt", "إيصال صرف للطبيب"),
	"entry": ("Doctor's Ledger Entry", "حركة حساب طبيب"),
	"cancelled": ("CANCELLED", "ملغى"),
	"draft": ("DRAFT", "مسودة"),
	"doctor": ("Paid To", "صُرف إلى"),
	"number": ("Receipt Number", "رقم الإيصال"),
	"date": ("Date", "التاريخ"),
	"agreement": ("Agreement", "الاتفاقية"),
	"period": ("Period", "الفترة"),
	"treasury": ("Paid From", "من خزنة"),
	"type": ("Type", "النوع"),
	"amount": ("Amount", "المبلغ"),
	"words": ("In Words", "المبلغ بالحروف"),
	"remarks": ("Remarks", "ملاحظات"),
	"received": ("Received By (Doctor)", "توقيع المستلم (الطبيب)"),
	"paid_by": ("Paid By (Accountant)", "توقيع المحاسب"),
} -%}
{%- macro t(key) -%}{{ L[key][1] if ar else L[key][0] }}{%- endmacro -%}
{%- set start = "right" if ar else "left" -%}
{%- set end = "left" if ar else "right" -%}
{%- set payout = doc.entry_type == "Payout" -%}

{%- set agreement = frappe.db.get_value("Doctor Agreement", doc.agreement, ["doctor"], as_dict=True) or {} -%}
{%- set doctor_name = frappe.db.get_value("Customer", agreement.doctor, "customer_name") if agreement.doctor else "" -%}
{%- set company_name = (frappe.db.get_value("Account", doc.treasury, "company") if doc.treasury else None)
	or frappe.defaults.get_global_default("company") -%}
{%- set company = frappe.db.get_value("Company", company_name, ["company_logo", "phone_no", "email", "default_currency"], as_dict=True) -%}

{%- set amount = doc.amount | abs -%}
{%- set pounds = amount | int -%}
{%- set piastres = (((amount - pounds) * 100) | round) | int -%}
{%- if ar -%}
	{%- set words = "فقط " ~ (frappe.utils.in_words(pounds) if pounds else "صفر") ~ " جنيه مصري"
		~ ((" و" ~ frappe.utils.in_words(piastres) ~ " قرشًا") if piastres else "") ~ " لا غير" -%}
{%- else -%}
	{%- set words = frappe.utils.money_in_words(amount, company.default_currency) -%}
{%- endif -%}

{% for page in layout %}
<div class="page-break payout-page" dir="{{ 'rtl' if ar else 'ltr' }}">

	<style>
		.payout-page { font-family: Inter, "DejaVu Sans", sans-serif; color: #171717; }
		.print-format-body { padding: 30px 12px 12px 12px !important; }
		.muted { color: #7c7c7c !important; }
		.doc-title { font-size: 20px; font-weight: 700; margin: 0 0 4px 0; }
		.status { color: #c0392b; font-weight: 700; margin: 8px 0; }
		.head { width: 100%; border-collapse: collapse; background: #f8f8f8; }
		.head td { padding: 14px 16px !important; vertical-align: top; }
		.company-name { font-size: 16px; font-weight: 700; }
		.logo { max-height: 60px; max-width: 120px; margin-bottom: 6px; border-radius: 8px; }
		.info-table { width: 100%; margin-top: 24px; border-collapse: collapse; }
		.info-table td { padding: 6px 8px !important; vertical-align: top; border-bottom: 1px solid #ededed; }
		.amount { margin-top: 20px; padding: 14px 16px; background: #f8f8f8; border-radius: 8px; }
		.amount-figure { font-size: 22px; font-weight: 700; }
		.signatures { width: 100%; margin-top: 64px; border-collapse: collapse; }
		.signatures td { width: 50%; padding: 0 16px !important; text-align: center; }
		.signature-line { border-top: 1px solid #171717; padding-top: 6px; margin-top: 40px; }
	</style>

	<div class="print-format-body">
		<table class="head">
			<tr>
				<td style="text-align: {{ start }}">
					{% if company.company_logo %}<img class="logo" src="{{ frappe.utils.get_url(company.company_logo) }}"><br>{% endif %}
					<div class="company-name">{{ company_name | e }}</div>
					{% if company.phone_no %}<div class="muted">{{ company.phone_no | e }}</div>{% endif %}
				</td>
				<td style="text-align: {{ end }}">
					<div class="doc-title">{{ t("title") if payout else t("entry") }}</div>
					<div class="muted">{{ doc.name }}</div>
				</td>
			</tr>
		</table>
		{%- if doc.docstatus == 2 -%}
			<div class="status" style="text-align: {{ start }}">{{ t("cancelled") }}</div>
		{%- elif doc.docstatus == 0 -%}
			<div class="status" style="text-align: {{ start }}">{{ t("draft") }}</div>
		{%- endif -%}

		<table class="info-table">
			<tr>
				<td class="muted" style="text-align: {{ start }}; width: 18%">{{ t("doctor") }}</td>
				<td style="text-align: {{ start }}; width: 32%"><b>{{ doctor_name | e }}</b></td>
				<td class="muted" style="text-align: {{ start }}; width: 18%">{{ t("number") }}</td>
				<td style="text-align: {{ start }}; width: 32%">{{ doc.name }}</td>
			</tr>
			<tr>
				<td class="muted" style="text-align: {{ start }}">{{ t("agreement") }}</td>
				<td style="text-align: {{ start }}">{{ doc.agreement | e }}</td>
				<td class="muted" style="text-align: {{ start }}">{{ t("date") }}</td>
				<td style="text-align: {{ start }}">{{ frappe.utils.format_date(doc.entry_date) }}</td>
			</tr>
			<tr>
				<td class="muted" style="text-align: {{ start }}">{{ t("period") }}</td>
				<td style="text-align: {{ start }}">{{ (doc.period or "") | e }}</td>
				{%- if payout -%}
				<td class="muted" style="text-align: {{ start }}">{{ t("treasury") }}</td>
				<td style="text-align: {{ start }}">{{ ((doc.treasury or "").rsplit(" - ", 1)[0]) | e }}</td>
				{%- else -%}
				<td class="muted" style="text-align: {{ start }}">{{ t("type") }}</td>
				<td style="text-align: {{ start }}">{{ _(doc.entry_type) }}</td>
				{%- endif -%}
			</tr>
			{%- if doc.remarks -%}
			<tr>
				<td class="muted" style="text-align: {{ start }}">{{ t("remarks") }}</td>
				<td colspan="3" style="text-align: {{ start }}">{{ doc.remarks | e }}</td>
			</tr>
			{%- endif -%}
		</table>

		<div class="amount" style="text-align: {{ start }}">
			<div class="muted">{{ t("amount") }}</div>
			<div class="amount-figure">{{ frappe.utils.fmt_money(amount, currency=company.default_currency) }}</div>
			<div class="muted" style="margin-top: 8px">{{ t("words") }}</div>
			<div>{{ words }}</div>
		</div>

		{%- if payout -%}
		<table class="signatures">
			<tr>
				<td><div class="signature-line">{{ t("received") }}</div></td>
				<td><div class="signature-line">{{ t("paid_by") }}</div></td>
			</tr>
		</table>
		{%- endif -%}
	</div>
</div>
{% endfor %}
